      var o = { id: r[0], domain: domain, level: r[1], prompt: r[2], choices: r[3].map(String), answer: String(r[3][0]),
        explain: r[4], hint1: r[5], hint2: r[6] }
      var k
      for (k in common || {}) o[k] = common[k]
      for (k in r[7] || {}) o[k] = r[7][k]
